public class Main {
    static BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));
    static FastScanner scanner = new FastScanner(System.in);

    public static void main(String[] args) throws Exception {
        long n = scanner.nextLong();
        long sum = 0, i = 0;

        while (sum + i + 1 <= n) {
            sum += i;
            i++;
        }

        println(n - sum);
        writer.flush();
    }

    static void println(Object a) throws IOException {
        writer.write(String.valueOf(a));
        writer.newLine();
    }

    static void print(Object a) throws IOException {
        writer.write(String.valueOf(a));
    }

    static void printf(String format, Object... args) throws IOException {
        writer.write(String.format(format, args));
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextFloat() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

